INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63766837', 63766837, 'analyze_legacy', 'Kementerian Ketenagakerjaan', 'central', 'Sekretariat Jenderal', 'Pembuatan Monitoring dan Analisis Media Cetak dan Online', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 200000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', 'Layanan pengelolaan pemantauan pemberitaan serta penyusunan analisis informasi media cetak dan media online yang dilaksanakan sepanjang Tahun Anggaran 2026 untuk mendukung fungsi komunikasi publik Biro Humas Kementerian Ketenagakerjaan. Ruang lingkup kegiatan mencakup pemantauan harian isu dan pemberitaan terkait Kemnaker beserta kebijakan/program ketenagakerjaan, pengumpulan dan pengarsipan kliping (cetak dan digital), pengelompokan topik serta pemetaan sentimen dan kecenderungan opini, identifikasi isu strategis dan potensi risiko reputasi, penyajian ringkasan eksekutif dan analisis naratif maupun kuantitatif (tren, intensitas pemberitaan, share of voice, serta kanal/aktor kunci), serta penyusunan laporan berkala dan insidentil sebagai bahan rekomendasi dan tindak lanjut komunikasi. Output layanan disampaikan secara tepat waktu, terukur, dan dapat dipertanggungjawabkan sesuai standar pelaporan yang ditetapkan Biro Humas, guna memperkuat pengambilan keputusan dan respons komunikasi publik yang cepat, akurat, dan terarah.', 'Spesifikasi pekerjaan ini mencakup penyediaan layanan monitoring pemberitaan media cetak dan media online sepanjang tahun 2026 melalui pemantauan harian atas isu/berita terkait Kementerian Ketenagakerjaan dan bidang ketenagakerjaan; pengumpulan, penyaringan, dan pengarsipan kliping (cetak dan digital) yang rapi dan mudah ditelusuri; pengelompokan berita per topik/unit kerja serta penilaian nada pemberitaan (positif, netral, negatif) dan tingkat urgensi isu; penyusunan analisis tren dan rekomendasi tindak lanjut komunikasi berbasis data; serta penyampaian produk laporan yang jelas dan ringkas berupa laporan harian/ringkasan isu, rekap mingguan, laporan bulanan, dan laporan insidentil saat terjadi isu mendesak, disertai data pendukung (tautan/sumber, tanggal, media, dan kutipan kunci) agar dapat digunakan sebagai bahan briefing pimpinan dan pengambilan keputusan komunikasi secara cepat dan akurat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1155013);
